sources.normalizeCrossElementEquip:
function normalizeCrossElementEquip(loadout,character){
        if(!loadout||!character||!Array.isArray(loadout.equippedSkills)){ return false; }
        let seen=false,changed=false;
        loadout.equippedSkills=loadout.equippedSkills.filter(skillId=>{
            const skill=skillById(skillId);
            if(!skill||!isCrossElementSkill(character,skill)){ return true; }
            if(!seen){ seen=true; return true; }
            changed=true; return false;
        }).slice(0,4);
        return changed;
    }

sources.equipSkill:
function equipSkill(skillId){
            const skill=skillById(skillId),context=getSkillContext();
            if(!skill||!context.character||!context.loadout||learnedLevel(context,skillId)<=0){ return false; }
            normalizeCrossElementEquip(context.loadout,context.character);
            const equipped=context.loadout.equippedSkills=context.loadout.equippedSkills||[];
            if(equipped.includes(skillId)){ return true; }
            if(isCrossElementSkill(context.character,skill)&&equipped.some(id=>{
                const equippedSkill=skillById(id); return equippedSkill&&isCrossElementSkill(context.character,equippedSkill);
            })){ return notify("每名角色最多攜帶 1 招跨元素技能。"); }
            if(equipped.length>=4){ return notify("每個角色最多只能攜帶4個技能。"); }
            equipped.push(skillId);
            if(typeof populateAutoSkillOptions==="function"){ populateAutoSkillOptions(); }
            if(typeof populateAutoSkillOptions2==="function"){ populateAutoSkillOptions2(); }
            finalizeSkillMutation();
            return true;
        }

sources.normalizeAction:
function normalizeAction(action){
        return typeof action==="string" && action
            ? action
            : "normal";
    }

sources.isEquippedAndLearnedAutoSkill:
function isEquippedAndLearnedAutoSkill(characterIndex,skillId){
        const skill=skillDatabase[skillId];
        const skillKey=getPartyCharacterKey(characterIndex);
        const loadout=characterSkillLoadouts[skillKey];

        return !!(
            skill &&
            !isUnsupportedAutoCategory(skill) &&
            loadout &&
            Array.isArray(loadout.equippedSkills) &&
            loadout.equippedSkills.includes(skillId) &&
            getSkillLevel(skillKey,skillId)>0
        );
    }

sources.rememberExplicitAction:
function rememberExplicitAction(characterIndex,action){
        const character=getPartyCharacterByIndex(characterIndex);
        if(!character){ return; }

        const config=getPartyAutoConfig(characterIndex);
        const selected=normalizeAction(action);

        config.skill=selected;

        if(selected==="normal"){
            config.v136ActionIntent="normal";
        }
        else if(selected==="defend"){
            config.v136ActionIntent="defend";
        }
        else{
            config.v136ActionIntent="skill";
            config.v136LastSkill=selected;
        }
    }

sources.migrateCurrentIntent:
function migrateCurrentIntent(characterIndex){
        const character=getPartyCharacterByIndex(characterIndex);
        if(!character){ return; }

        const config=getPartyAutoConfig(characterIndex);
        const selected=normalizeAction(config.skill);

        if(config.v136ActionIntent){ return; }

        if(selected==="normal"){
            config.v136ActionIntent="normal";
        }
        else if(selected==="defend"){
            config.v136ActionIntent="defend";
        }
        else{
            config.v136ActionIntent="skill";
            config.v136LastSkill=selected;
        }
    }

sources.restoreSkillAfterLegacySync:
function restoreSkillAfterLegacySync(characterIndex){
        const config=getPartyAutoConfig(characterIndex);

        if(
            config.v136ActionIntent==="skill" &&
            config.skill==="normal" &&
            isEquippedAndLearnedAutoSkill(characterIndex,config.v136LastSkill)
        ){
            config.skill=config.v136LastSkill;
            return true;
        }

        return false;
    }

sources.removeEquippedSkill:
function removeEquippedSkill(index){

    const character =
        characterSkillLoadouts[
            currentSkillCharacter
        ];


    if(!character){
        return;
    }


    character.equippedSkills
        .splice(
            index,
            1
        );


    renderSkillLoadout();

    populateAutoSkillOptions();

    populateAutoSkillOptions2();

    saveGame();

}

sources.getSkillLevel:
function getSkillLevel(characterId,skillId){

    const loadout =
        characterSkillLoadouts[
            characterId
        ];


    if(
        !loadout ||
        !loadout.skillLevels
    ){
        return 0;
    }


    return (
        loadout.skillLevels[
            skillId
        ]||
        0
    );

}
